import { useEffect, useState, useCallback } from 'react';
import axios from 'axios';
import '../styles/messageCenter.css';

function MessageCenter() {
  const [messages, setMessages] = useState([]);
  const [form, setForm] = useState({ receiverId: '', itemId: '', content: '' });
  const senderId = localStorage.getItem('userId');
  const senderName = localStorage.getItem('username') || 'You';

  const fetchMessages = useCallback(async () => {
    try {
      const res = await axios.get(`${process.env.REACT_APP_API_URL}/api/messages/user`, {
        params: { userId: senderId }
      });
      setMessages(res.data);
    } catch (err) {
      console.error('Fetch error:', err.response?.data || err.message);
    }
  }, [senderId]);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const receiverId = params.get('receiverId');
    const itemId = params.get('itemId');

    if (receiverId || itemId) {
      setForm(prev => ({
        ...prev,
        receiverId: receiverId || '',
        itemId: itemId || ''
      }));
    }

    fetchMessages();
    const interval = setInterval(fetchMessages, 5000);
    return () => clearInterval(interval);
  }, [fetchMessages]);

  useEffect(() => {
    const chatEnd = document.getElementById('chat-end');
    if (chatEnd) chatEnd.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const sendMessage = async (e) => {
    e.preventDefault();
    if (!form.receiverId.trim() || !form.itemId.trim() || !form.content.trim()) {
      alert('Please fill in all fields: Receiver ID, Item ID, and Message.');
      return;
    }
    try {
      await axios.post(`${process.env.REACT_APP_API_URL}/api/messages/send`, {
        ...form,
        senderId
      });
      setForm({ receiverId: '', itemId: '', content: '' });
      fetchMessages();
    } catch (err) {
      console.error('Send error:', err.response?.data || err.message);
    }
  };

  const addReaction = async (messageId, emoji) => {
    try {
      await axios.post(`${process.env.REACT_APP_API_URL}/api/messages/react`, {
        messageId,
        emoji,
        userId: senderId
      });
      fetchMessages();
    } catch (err) {
      console.error('Reaction error:', err.response?.data || err.message);
    }
  };

  const groupedMessages = messages.reduce((acc, msg) => {
    const itemKey = msg.itemId?._id || msg.itemId;
    if (!acc[itemKey]) {
      acc[itemKey] = {
        item: msg.itemId,
        messages: []
      };
    }
    acc[itemKey].messages.push(msg);
    return acc;
  }, {});

  return (
    <div className="message-center">
      <h2>Message Center</h2>

      <form className="message-form" onSubmit={sendMessage}>
        <p><strong>Sending as:</strong> {senderName}</p>
        <input
          name="receiverId"
          placeholder="Receiver User ID"
          value={form.receiverId}
          onChange={e => setForm({ ...form, receiverId: e.target.value })}
          required
        />
        <input
          name="itemId"
          placeholder="Item ID"
          value={form.itemId}
          onChange={e => setForm({ ...form, itemId: e.target.value })}
          required
        />
        <textarea
          name="content"
          placeholder="Type something kind, helpful, or hopeful..."
          value={form.content}
          onChange={e => setForm({ ...form, content: e.target.value })}
          required
        />
        <button type="submit">Send Message</button>
      </form>

      {Object.entries(groupedMessages).map(([itemId, group]) => (
        <div key={itemId} className="group-thread">
          <h3 className="group-title">🧾 {group.item?.title || 'Untitled Group'}</h3>
          <div style={{ display: 'flex', flexDirection: 'column' }}>
            {group.messages.map(msg => {
              const isSender = msg.senderId === senderId || msg.senderId?._id === senderId;
              const senderLabel = isSender ? 'You' : msg.senderId?.username || 'User';
              return (
                <div key={msg._id} className={`message-bubble ${isSender ? 'sender' : 'receiver'}`}>
                  <p>{msg.content}</p>
                  <div className="message-meta">
                    {senderLabel} • {new Date(msg.timestamp).toLocaleTimeString()}
                  </div>
                  <div className="reactions">
                    {['❤️', '👍', '😢'].map(emoji => (
                      <span key={emoji} onClick={() => addReaction(msg._id, emoji)}>{emoji}</span>
                    ))}
                  </div>
                  {msg.reactions?.length > 0 && (
                    <div className="reactions">
                      {msg.reactions.map((r, i) => <span key={i}>{r.emoji}</span>)}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      ))}
      <div id="chat-end" />
    </div>
  );
}

export default MessageCenter;
